 return {mode,width:1000,phase:'working',held:null,links:[],flow:[],passiveFlow:[],spills:[],time:0,reactionHeat:0,fuelHeat:0,bypassHeat:0,airHeat:0,boilingHeat:0,vapour:0,fuelBurned:0,initial:null,final:null,massReadings:[],readings:[],initialMaterials:{water:mode==='neutralisation'?700:500,acid:mode==='neutralisation'?.1:0,base:mode==='neutralisation'?.1:0,fuel:mode==='combustion'?2:0},items};
