export const active=o=>o&&!o.stored;
export function point(o,x=0,y=0){const a=o.angle*Math.PI/180;return{x:o.x+x*Math.cos(a)-y*Math.sin(a),y:o.y+x*Math.sin(a)+y*Math.cos(a)};}
export const heatCapacity=o=>(o.dryCapacity||0)+o.water*THERMAL.waterCp;
export const temperature=o=>heatCapacity(o)>EPS?AMBIENT+o.energy/heatCapacity(o):AMBIENT;
export const objective=s=>s.items[s.mode==='neutralisation'?'cup':'can'];
export function targetAt(s,p,exclude,inside=false){return Object.values(s.items).filter(o=>active(o)&&o.id!==exclude&&'water'in o&&Math.abs(o.angle)<20&&Math.abs(p.x-o.x)<(o.kind==='cylinder'?28:o.kind==='cup'||o.kind==='can'?50:44)&&(inside?p.y>=o.y-15&&p.y<=o.y+(o.kind==='cup'||o.kind==='cylinder'?120:100):p.y<=o.y+20&&o.y-p.y<200)).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];}
export function toolTarget(s,id){const o=s.items[id];if(!active(o))return null;const p=point(o,0,o.kind==='thermometer'?160:95);return targetAt(s,p,id,true)||targetAt(s,p,id);}
function parcel(o,ml){const water=Math.min(Math.max(0,ml),o.water),f=o.water>EPS?water/o.water:0,t=temperature(o),m={water,acid:o.acid*f,base:o.base*f,reacted:o.reacted*f,energy:water*THERMAL.waterCp*(t-AMBIENT)};for(const k of ['water','acid','base','reacted','energy'])o[k]-=m[k];if(o.water<EPS){o.water=0;o.acid=0;o.base=0;o.reacted=0;}return m;}
function add(s,o,m){for(const k of ['water','acid','base','reacted','energy'])o[k]+=m[k];const extent=Math.max(0,Math.min(o.acid,o.base)-o.reacted),q=extent*THERMAL.neutralisation;o.reacted+=extent;o.energy+=q;s.reactionHeat+=q;o.mixed=false;}
function spill(s,p,m){if(m.water<=EPS)return;let o=s.spills.find(o=>Math.abs(o.x-p.x)<25);if(!o){o={x:p.x,water:0,acid:0,base:0,reacted:0,energy:0};s.spills.push(o);}add(s,o,m);}
function receive(s,to,m,p){const f=to&&m.water>EPS?Math.min(1,Math.max(0,to.capacity-to.water)/m.water):0;if(to)add(s,to,Object.fromEntries(Object.entries(m).map(([k,v])=>[k,v*f])));spill(s,p,Object.fromEntries(Object.entries(m).map(([k,v])=>[k,v*(1-f)])));}
export function transfer(s,fromId,toId,ml){const a=s.items[fromId],b=s.items[toId];if(s.phase!=='working'||!active(a)||!active(b)||!('water'in a)||!('water'in b)||a===b||!Number.isFinite(ml)||ml<=0)return 0;const m=parcel(a,ml);receive(s,b.id==='cup'&&s.items.lid?.parent==='cup'?null:b,m,point(b));s.flow=[{from:point(a),to:point(b)}];return m.water;}
export function pour(s,id,ml=10){const o=s.items[id];if(!active(o)||!('water'in o))return 0;if(id==='cup'&&s.items.lid?.parent==='cup')return 0;const to=targetAt(s,point(o,0,-5),id);return to?transfer(s,id,to.id,ml):0;}
export function stir(s,id){const o=s.items[id];if(s.phase!=='working'||!active(o)||!('water'in o)||o.water<EPS)return false;o.mixed=true;return true;}
export function fitLid(s){const l=s.items.lid,c=s.items.cup;if(s.phase!=='working'||!active(l)||!active(c)||Math.abs(l.x-c.x)>55||Math.abs(l.y-c.y)>65)return false;l.parent='cup';Object.assign(l,point(c,0,-8));l.angle=c.angle;physicsFor(s).sync();return true;}
export function immersed(s){const p=s.items.probe,o=toolTarget(s,'probe');if(!active(p)||!o||o.water<EPS)return null;const tip=point(p,0,160),h=o.kind==='cup'||o.kind==='cylinder'?120:100,surface=o.y+h-6-(o.kind==='cylinder'?96:h-18)*Math.min(1,o.water/o.capacity);return tip.y>=surface&&tip.y<o.y+h+2?o:null;}
export function clipProbe(s){const p=s.items.probe,o=toolTarget(s,'probe');if(s.phase!=='working'||!active(p)||!o)return false;p.parent=o.id;p.clipOffset={x:o.kind==='cylinder'?8:15,y:o.kind==='can'?-75:o.kind==='beaker'?-65:-55};Object.assign(p,point(o,p.clipOffset.x,p.clipOffset.y));p.angle=o.angle;physicsFor(s).sync();return true;}
export function recordTemperature(s,which){if(s.phase!=='working'||!['initial','final'].includes(which))return null;const o=immersed(s);if(!o)return null;const r={target:o.id,time:s.time,temperature:Number(s.items.probe.reading.toFixed(2)),water:o.water,acid:o.acid,base:o.base,reacted:o.reacted,mixed:o.mixed,capacity:heatCapacity(o)};s[which]=r;s.readings.push({...r,which});return r;}
export function balanceLoad(s){const b=s.items.balance;if(!active(b))return null;return Object.values(s.items).find(o=>active(o)&&o.id!=='balance'&&Math.abs(o.angle)<12&&Math.abs(o.x-b.x)<48&&Math.abs(o.y+(o.kind==='burner'?60:o.kind==='can'?100:999)-(b.y+4))<9)||null;}
export function balanceReading(s){const o=balanceLoad(s);return o?o.kind==='burner'?o.dryMass+o.fuel:THERMAL.aluminiumMass+o.water:0;}
export function recordMass(s){if(s.phase!=='working')return null;const o=balanceLoad(s);if(!o)return null;const r={item:o.id,mass:Number(balanceReading(s).toFixed(3)),time:s.time,on:o.on||false};s.massReadings.push(r);return r;}
export function coupling(s){const b=s.items.burner,c=s.items.can;if(!active(b)||!active(c)||Math.abs(b.angle)>20||Math.abs(c.angle)>20)return 0;const bottom=point(c,0,100),gap=b.y-bottom.y,dx=Math.abs(b.x-bottom.x);if(gap<20||gap>180||dx>65)return 0;return .42*Math.max(0,1-Math.abs(gap-80)/150)*Math.max(0,1-dx/65);}
export function toggleBurner(s){const b=s.items.burner;if(s.phase!=='working'||!active(b))return false;if(b.on){b.on=false;return true;}if(b.fuel<=EPS)return false;b.on=true;return true;}
export function stepThermal(s,dt){if(s.phase!=='working'||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,.05);s.time+=dt;
 const b=s.items.burner,c=s.items.can;if(active(b)&&b.on){const mass=Math.min(b.fuel,THERMAL.burnRate*dt);b.fuel-=mass;s.fuelBurned+=mass;const q=mass*THERMAL.ethanolEnergy,captured=q*coupling(s);s.fuelHeat+=q;s.bypassHeat+=q-captured;if(captured>0)c.energy+=captured;if(b.fuel<EPS)b.on=false;}
 for(const o of [...Object.values(s.items).filter(o=>active(o)&&'water'in o),...s.spills]){const capacity=heatCapacity(o);if(capacity<=EPS)continue;const lid=o.id==='cup'&&s.items.lid?.parent==='cup'&&!s.items.lid.stored,g=o.kind==='cup'?(lid?.25:.9):o.kind==='can'?.7:1.0,loss=o.energy*(1-Math.exp(-g*dt/capacity));o.energy-=loss;s.airHeat+=loss;const maximum=capacity*80;if(o.water>EPS&&o.energy>maximum){const mass=Math.min(o.water,(o.energy-maximum)/2260),q=mass*(2260+THERMAL.waterCp*80);o.water-=mass;o.energy-=q;s.vapour+=mass;s.boilingHeat+=q;}}
 const o=immersed(s),target=o?temperature(o):20,p=s.items.probe,tau=o&&!o.mixed?6:1.2;p.reading+=(target-p.reading)*(1-Math.exp(-dt/tau));
}
export function materials(s){const pools=Object.values(s.items).filter(o=>'water'in o).concat(s.spills),t=pools.reduce((n,o)=>({water:n.water+o.water,acid:n.acid+o.acid,base:n.base+o.base}),{water:0,acid:0,base:0});return {...t,water:t.water+s.vapour,fuel:(s.items.burner?.fuel||0)+s.fuelBurned};}
export function energyBalance(s){const stored=Object.values(s.items).filter(o=>'water'in o).concat(s.spills).reduce((n,o)=>n+o.energy,0);return {generated:s.reactionHeat+s.fuelHeat,accounted:stored+s.airHeat+s.bypassHeat+s.boilingHeat,stored,air:s.airHeat,bypass:s.bypassHeat,boiling:s.boilingHeat};}
export function outcome(s){const a=s.initial,b=s.final,target=objective(s),delta=a&&b?b.temperature-a.temperature:0,mass=b?.water||0,q=mass*THERMAL.waterCp*delta,reacted=b?b.reacted-(a?.reacted||0):0,reads=s.massReadings.filter(r=>r.item==='burner'),fuel=reads.length>1?reads[0].mass-reads.at(-1).mass:0,canQ=q+THERMAL.aluminiumMass*THERMAL.aluminiumCp*delta,valid=a&&b&&a.target===target.id&&b.target===target.id&&b.time>a.time&&delta>0&&b.mixed&&mass>0;return {success:Boolean(valid&&(s.mode==='neutralisation'?reacted>EPS:fuel>EPS&&!s.items.burner.on)),delta,mass,q:s.mode==='neutralisation'?q:canQ,reacted,fuel,enthalpy:s.mode==='neutralisation'?reacted>EPS?-q/reacted/1000:0:fuel>EPS?-canQ/(fuel/THERMAL.ethanolMolarMass)/1000:0};}
const worlds=new WeakMap();
